    "case.perlemStatuses.alt08": "Before: the Assignment statuses card on the home screen with counts for needs rework, time to start and under review",
    "case.perlemStatuses.alt09": "After: the To-do card with status tiles and lines about overdue and upcoming deadlines",
    "case.perlemStatuses.alt10": "Before: assignments grouped by subject, with separate cards under each subject",
    "case.perlemStatuses.alt11": "After: one assignment list grouped by status: Needs rework, Time to start and Under review",
    "case.perlemStatuses.alt12": "Assignment list with filters by subject and level, showing Biology",
    "case.perlemStatuses.alt13": "Assignment list filtered by status, showing only Time to start",
