    "case.perlemStatuses.cap05": ["New user flow", "Original working artifact, in Russian"],
    "case.perlemStatuses.cap06": ["Concept for the product owner", "Original working artifact, in Russian"],
    "case.perlemStatuses.cap08": "Before: Home card",
